use hs_loop::repl::ReplSession;
fn rig(d:&std::path::Path,settings:&str)->std::path::PathBuf{let cfg=d.join("rig");std::fs::write(&cfg,format!("{settings}\n[[models]]\nname='seqmodel'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-seqmodel"))).unwrap();cfg}
#[test]fn invalid_deployment_plan_config_fails_at_load(){for s in ["[plan]\n", "[plan]\nsection=' '", "[plan]\nsection=1", "[plan]\nsection='Guide'\nunknown=true"]{let d=tempfile::tempdir().unwrap();let cfg=rig(d.path(),s);assert!(ReplSession::load(&cfg,&d.path().join("run"),false,Some(1)).is_err(),"{s}");}}
#[test]fn invalid_deployment_plan_config_fails_at_resume(){let d=tempfile::tempdir().unwrap();let cfg=rig(d.path(),"[plan]\nsection='Guide'");let log=d.path().join("run");let s=ReplSession::load(&cfg,&log,false,Some(1)).unwrap();let id=s.stream_id();drop(s);rig(d.path(),"[plan]\nsection='Guide'\nunknown=true");assert!(ReplSession::load_resume(&cfg,&log,false,Some(1),id).is_err());}
#[test]fn absent_plan_config_remains_backward_compatible(){let d=tempfile::tempdir().unwrap();let cfg=rig(d.path(),"");let log=d.path().join("run");let s=ReplSession::load(&cfg,&log,false,Some(1)).unwrap();let id=s.stream_id();drop(s);assert!(ReplSession::load_resume(&cfg,&log,false,Some(1),id).is_ok());}
#[test]fn deployment_guidance_is_session_owned_and_model_visible_after_restore(){let d=tempfile::tempdir().unwrap();let cfg=rig(d.path(),"[plan]\nsection='Owner-selected planning guide.'");let log=d.path().join("run");let mut s=ReplSession::load(&cfg,&log,false,Some(1)).unwrap();s.select_plan_mode(true).unwrap();s.run_goal("Plan work").unwrap();let id=s.stream_id();drop(s);let mut s=ReplSession::load_resume(&cfg,&log,false,Some(1),id).unwrap();assert_eq!(s.plan_view()["active"],true);s.run_goal("Continue work").unwrap();let r=hs_log::StreamReader::open(&log,id).unwrap();let vals:Vec<serde_json::Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice::<serde_json::Value>(&r.resolve_payload(e).ok()?).ok()).filter(|v|v["messages"].is_array()).collect();assert_eq!(vals.len(),2);for v in vals{assert!(v["messages"].as_array().unwrap().iter().any(|m|m["content"]=="Owner-selected planning guide."));}}
